using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using Assets.Script.DynamicCards;
public static class MotionWork {public static void Run(){new GameObject("Tempest layer audit").AddComponent<TempestLayerAudit>();}}
public class TempestLayerAudit:MonoBehaviour {
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionRepair-20260910/TempestLayers/";
object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
void Save(DynamicCardView v,string name){var cam=(Camera)F(v,"renderCamera");cam.Render();var rt=(RenderTexture)F(v,"texture");var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;File.WriteAllBytes(W+name+".png",t.EncodeToPNG());Destroy(t);}
IEnumerator Start(){Directory.CreateDirectory(W);var v=FindObjectsOfType<DynamicCardView>().First(x=>(string)F(x,"artId")=="202203"&&F(x,"model")!=null);var model=(GameObject)F(v,"model");var rs=model.GetComponentsInChildren<Renderer>(true);var enabled=rs.Select(x=>x.enabled).ToArray();File.WriteAllLines(W+"renderers.txt",rs.Select((r,i)=>i+" "+r.name+" "+string.Join(";",r.sharedMaterials.Where(x=>x!=null).Select(x=>x.name+"/"+x.shader.name+" flow="+(x.HasProperty("_FlowAnimSpeed")?x.GetFloat("_FlowAnimSpeed"):0)+" dist="+(x.HasProperty("_FlowAnimDist")?x.GetFloat("_FlowAnimDist"):0)))));for(int t=0;t<2;t++){for(int i=0;i<rs.Length;i++){for(int j=0;j<rs.Length;j++)rs[j].enabled=i==j&&enabled[j];Save(v,i+"-"+t);}for(int j=0;j<rs.Length;j++)rs[j].enabled=enabled[j];Save(v,"full-"+t);yield return new WaitForSecondsRealtime(2.5f);}Destroy(gameObject);}}
